"""Regenerate Markdown tables from the recorded CSV measurements."""
import csv,pathlib,statistics
root=pathlib.Path(__file__).resolve().parents[1]
rows=list(csv.DictReader((root/'results/baseline.csv').open()))
paired=list(csv.DictReader((root/'results/optimization.csv').open()))
lines=['# Final measurements','', 'Linux x86_64 virtual environment; AMD EPYC 9V45 reported by /proc/cpuinfo; GCC 14.2.0; C++17; -O2. Name sorting, homework average, five homework grades. Deterministic input generated by --generate; 40% pass and 60% fail. These observations are not universal speed rankings.','', '## Six-way baseline survey','', 'One isolated process per case. Times include reading, sorting, splitting and output-file writing. Memory probes, CSV logging, destruction and UI are outside the timed total. Caches were not cleared; this is an exploratory single-run survey, so small differences are inconclusive.','', '| N | Container | Strategy | Read ms | Sort ms | Split ms | Write ms | Total ms | RSS after split MiB | Peak RSS MiB |','|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in rows:
 vals=[r['students'],r['container'],r['strategy']]+[f"{float(r[k]):.3f}" for k in ['read_ms','sort_ms','split_ms','write_ms','total_ms']]+[f"{int(r[k])/1024:.2f}" if int(r[k])>=0 else 'unavailable' for k in ['rss_after_split_kib','peak_rss_kib']]
 lines.append('| '+' | '.join(vals)+' |')
large=[r for r in rows if r['students']=='10000000'];best=min(large,key=lambda r:float(r['total_ms']))
lines+=['', f"At 10M records the lowest surveyed total was {best['container']} strategy {best['strategy']} ({float(best['total_ms'])/1000:.3f} seconds). List/strategy 2 was selected for the focused refactor; it also retains fewer live records than strategy 1.", '', '## Paired before/after: list, strategy 2','', 'Three fresh processes per implementation per size. Implementation order alternates per repetition. Medians are shown. Baseline uses the previous manual compaction loop. Algorithms uses std::find_if and list::splice, transferring failed nodes without allocating/copying their Student data. Input generation is excluded.','', '| N | Baseline split ms | Algorithms split ms | Baseline total ms | Algorithms total ms | Split improvement % | Total improvement % |','|---:|---:|---:|---:|---:|---:|---:|']
for n in [1000,10000,100000,1000000,10000000]:
 groups={i:[r for r in paired if int(r['students'])==n and r['implementation']==i] for i in ['baseline','algorithms']}
 assert all(len(v)==3 for v in groups.values())
 b,a=[statistics.median(float(r['split_ms']) for r in groups[i]) for i in groups]
 bt,at=[statistics.median(float(r['total_ms']) for r in groups[i]) for i in groups]
 lines.append(f'| {n} | {b:.3f} | {a:.3f} | {bt:.3f} | {at:.3f} | {(b-a)/b*100:.2f} | {(bt-at)/bt*100:.2f} |')
lines+=['', 'Negative improvement means a slowdown. Sorting and I/O often dominate total time; reduced grouping time does not guarantee a faster total on every run. Repeated runs reduce but do not eliminate shared-environment noise.', '', '## Memory interpretation','', 'RSS after splitting comes from /proc/self/status (VmRSS); process peak RSS comes from getrusage. Linux measurements are in KiB; table values divide by 1024. Unsupported platforms report -1, not a fabricated zero. Peak RSS spans the entire process, including allocator behavior and inherited process overhead. The two OS counters may differ slightly due to accounting/sampling. Use the fresh-process CLI for comparable peak measurements; interactive repeated runs have cumulative process peaks.','', 'Strategy 1 holds the original N records plus N copies in the two groups (2N total). Strategy 2 holds N live records across its original and failed groups. Logical counts are not bytes: vector capacity, deque blocks, list nodes, allocator retention and strings/homework allocations matter. The baseline does not call shrink_to_fit, so erasing reduces logical size without guaranteeing capacity release.', '', '| Container (10M) | Strategy 1 RSS MiB | Strategy 2 RSS MiB | Reduction % |','|---|---:|---:|---:|']
for c in ['vector','list','deque']:
 one=next(r for r in large if r['container']==c and r['strategy']=='1');two=next(r for r in large if r['container']==c and r['strategy']=='2')
 a,b=[int(r['rss_after_split_kib']) for r in [one,two]]
 lines.append(f'| {c} | {a/1024:.2f} | {b/1024:.2f} | {(a-b)/a*100:.2f} |')
lines+=['', 'The measured largest cases support the claim that Strategy 2 saves resident memory. They do not establish an exact twofold saving. The optimized list implementation additionally avoids transient duplicate failed nodes. Raw timings, counts and memory readings are preserved in results/*.csv.']
(root/'RESULTS.md').write_text('\n'.join(lines)+'\n')
